      @charset "UTF-8";#globalheader{all:unset} /* ... a többi CSS ... */

      /* --- Kiegészítő stílusok a csevegőfelülethez --- */
      body {
        font-family: "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
        background-color: #f5f5f7;
        color: #1d1d1f;
        display: flex;
        flex-direction: column;
        align-items: center;
