            <div class="input-container">
                <input type="text" id="query-input" placeholder="Üzenet vagy kutatási téma...">
                <div class="button-group">
                    <button id="send-btn">Küldés</button>
                    <button id="deep-search-btn">Deep Search</button>
                </div>
            </div>
        </div>
    </div>

    <script>
      const queryInput = document.getElementById('query-input');
      const sendBtn = document.getElementById('send-btn');
      const deepSearchBtn = document.getElementById('deep-search-btn');
      const responseArea = document.getElementById('response-area');
      const spinner = document.getElementById('loading-spinner');
      let eventSource;

      // Egyedi EventSource implementáció a POST kérésekhez
      function createEventSource(url, options) {
          const { method, headers, body } = options;

          fetch(url, {
              method: method,
              headers: headers,
              body: body
          }).then(response => {
              const reader = response.body.getReader();
              const decoder = new TextDecoder('utf-8');

              if(eventSource && eventSource.onopen) eventSource.onopen();

              function push() {
                  reader.read().then(({ done, value }) => {
                      if (done) {
                          if(eventSource && eventSource.onerror) eventSource.onerror(new Error("Stream ended"));
                          return;
                      }

                      const chunk = decoder.decode(value, {stream: true});
                      // A stream több "data:" eseményt is tartalmazhat
                      const messages = chunk.split('\n\n');
                      messages.forEach(message => {
                          if (message.startsWith('data:')) {
                               const data = message.substring(5).trim();
                               if (data === '[DONE]') {
                                   if(eventSource) eventSource.close();
                                   return;
                               }
                               if (data) {
                                  if(eventSource && eventSource.onmessage) {
                                      eventSource.onmessage({ data: data });
                                  }
                               }
                          }
                      });
                      push();
                  }).catch(err => {
                      if(eventSource && eventSource.onerror) eventSource.onerror(err);
                  });
              }
              push();
          }).catch(err => {
              if(eventSource && eventSource.onerror) eventSource.onerror(err);
          });

          let es = {
              onopen: null,
              onmessage: null,
              onerror: null,
              close: function() {
                  // A fetch kapcsolatot nehéz megszakítani, de a callbackeket nullázzuk
                  this.onopen = this.onmessage = this.onerror = null;
              }
          };
          return es;
      }

