        const query = queryInput.value;
        if (!query) {
          queryInput.focus();
          return;
        }

        if (eventSource) {
          eventSource.close();
        }

        responseArea.innerHTML = '';
        spinner.style.display = 'block';

        eventSource = createEventSource(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ query: query })
        });

        eventSource.onopen = () => {
          spinner.style.display = 'none';
        };

        eventSource.onmessage = (event) => {
          // A backend Nim kód most már a JSON objektumot küldi
          // a "delta" -> "content" mezővel, így azt közvetlenül
          // hozzáadhatjuk.
          responseArea.innerHTML += event.data;
          responseArea.scrollTop = responseArea.scrollHeight; // Automatikus görgetés
        };

        eventSource.onerror = (err) => {
          console.error("EventSource hiba:", err);
          spinner.style.display = 'none';
          if (responseArea.innerHTML.trim() === '') {
             responseArea.innerHTML = "\n\nHiba történt a kapcsolat során. Kérjük, ellenőrizze a backend szervert és az API kulcsokat.";
          }
          if(eventSource) eventSource.close();
        };
      }

      sendBtn.addEventListener('click', () => handleRequest('/chat'));
      deepSearchBtn.addEventListener('click', () => handleRequest('/deepsearch'));
      queryInput.addEventListener('keypress', (e) => {
          if (e.key === 'Enter') {
              sendBtn.click();
          }
      });
    </script>
